sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.facility-card {

    background: #ffffff;

    border-radius: 16px;

    padding: 20px;

    box-shadow: 0 4px 15px rgba(0,0,0,0.08);

    height: 100%;
}

.facility-header {

    font-size: 20px;

    font-weight: 600;

    color: #0d2d62;

    margin-bottom: 15px;
}

.facility-status {

    background: #eef5ff;

    border-radius: 10px;

    padding: 10px;

    font-weight: 600;

    color: #0d2d62;

    margin-bottom: 15px;
}

.status-circle {

    display: inline-block;

    width: 10px;

    height: 10px;

    border-radius: 50%;

    background: #28a745;

    margin-right: 8px;
}

.facility-summary {

    background: #f8fbff;

    border-left: 4px solid #1f6bff;

    padding: 12px;

    border-radius: 8px;

    margin-bottom: 15px;

    color: #444;
}

.facility-metrics {

    display: flex;

    justify-content: space-between;

    gap: 10px;

    margin-bottom: 15px;
}

.metric-box {

    flex: 1;

    background: linear-gradient(
        135deg,
        #0d2d62,
        #1f6bff
    );

    color: white;

    text-align: center;

    border-radius: 12px;

    padding: 12px;
}

.metric-value {

    font-size: 24px;

    font-weight: bold;
}

.metric-label {

    font-size: 12px;
}

.priority-section ul {

    padding-left: 18px;
}

sp_widget.script:
(function() {

    data.status = "Facility Operating Normally";

    data.adherence = 96;

    data.attention = 3;

    data.refills = 2;

    data.summary =
        "Overall medication adherence remains strong today. Three residents require follow-up and two refill requests are awaiting approval.";

    data.priorityPatients = [

        {name: "Samantha - Missed morning medication"},

        {name: "Lakshmi - Refill request pending"},

        {name: "Robert Brown - Delayed medication administration"}

    ];

})();
